84	// DownloadTemplate downloads and extracts a template from the registry
85	func (c *Client) DownloadTemplate(repository, tag string) (*Template, error) {
86		// Get manifest
87		manifestURL := fmt.Sprintf("%s/v2/%s/manifests/%s", c.registryURL, repository, tag)
88	
89		req, err := http.NewRequest("GET", manifestURL, nil)
90		if err != nil {
91			return nil, err
92		}
93	
94		req.Header.Set("Accept", "application/vnd.oci.image.manifest.v1+json")
95		if c.username != "" && c.REDACTED != "" {
96			req.SetBasicAuth(c.username, c.REDACTED)
97		}
98	
99		resp, err := c.httpClient.Do(req)
100		if err != nil {
101			return nil, err
102		}
103		defer func() { _ = resp.Body.Close() }()
104	
105		if resp.StatusCode != http.StatusOK {
106			return nil, fmt.Errorf("failed to get manifest: %s", resp.Status)
107		}
108	
109		var manifest struct {
110			Layers []struct {
111				MediaType string `json:"mediaType"`
