147		if c.username != "" && c.REDACTED != "" {
148			req.SetBasicAuth(c.username, c.REDACTED)
149		}
150	
151		resp, err := c.httpClient.Do(req)
152		if err != nil {
153			return nil, err
154		}
155		defer func() { _ = resp.Body.Close() }()
156	
157		if resp.StatusCode != http.StatusOK {
158			return nil, fmt.Errorf("failed to download layer: %s", resp.Status)
