164	// Limits bounds what reading an archive may hold in memory. A zero field is no
165	// limit on that axis.
166	type Limits struct {
167		Files int   // regular files
168		Bytes int64 // their content, once decompressed
169	}
170	
171	// ErrNotRegularFile is returned for an archive entry that is a link, a device
172	// or anything else that is not a regular file.
173	var ErrNotRegularFile = errors.New("archive entry is not a regular file")
174	
175	// ErrArchiveTooLarge is returned when an archive exceeds its Limits.
176	var ErrArchiveTooLarge = errors.New("archive is larger than allowed")
177	
178	// ReadTarGz reads a gzipped tar archive into its regular files.
179	func ReadTarGz(r io.Reader) ([]ArchiveFile, error) {
180		return ReadTarGzLimited(r, Limits{})
181	}
182	
183	// ReadTarGzLimited is ReadTarGz that stops, with ErrArchiveTooLarge, as soon as
184	// the archive passes lim — before the rest of it is decompressed.
185	func ReadTarGzLimited(r io.Reader, lim Limits) ([]ArchiveFile, error) {
186		gzr, err := gzip.NewReader(r)
187		if err != nil {
188			return nil, err
189		}
190		defer func() { _ = gzr.Close() }()
191		return ReadTarLimited(gzr, lim)
192	}
193	
194	// ReadTar reads a tar archive into its regular files.
195	//
196	// Directories and pax headers are skipped. Anything else that is not a regular
197	// file — a symlink, a hard link, a device — is refused rather than read: the
198	// old behavior turned a symlink into an empty file, which is a template
199	// silently missing what it says it contains.
200	func ReadTar(r io.Reader) ([]ArchiveFile, error) {
201		return ReadTarLimited(r, Limits{})
202	}
203	
204	// ReadTarLimited is ReadTar that refuses, with ErrArchiveTooLarge, an archive
205	// past lim without reading the rest of it into memory.
206	func ReadTarLimited(r io.Reader, lim Limits) ([]ArchiveFile, error) {
207		tr := tar.NewReader(r)
208		var files []ArchiveFile
209		var total int64
210	
211		for {
212			header, err := tr.Next()
213			if err == io.EOF {
214				break
215			}
216			if err != nil {
217				return nil, err
218			}
219	
220			switch header.Typeflag {
221			case tar.TypeDir, tar.TypeXGlobalHeader:
222				continue
223			case tar.TypeReg:
224			default:
225				return nil, fmt.Errorf("%w: %q (type %q)", ErrNotRegularFile, header.Name, header.Typeflag)
226			}
227	
228			if lim.Files > 0 && len(files) >= lim.Files {
229				return nil, ErrArchiveTooLarge
230			}
231			var src io.Reader = tr
232			if lim.Bytes > 0 {
233				// One byte past what is left is enough to tell "exactly at the
234				// limit" from "over it".
235				src = io.LimitReader(tr, lim.Bytes-total+1)
236			}
237			content, err := io.ReadAll(src)
238			if err != nil {
239				return nil, err
240			}
241			total += int64(len(content))
242			if lim.Bytes > 0 && total > lim.Bytes {
243				return nil, ErrArchiveTooLarge
244			}
245	
246			path, err := sanitizeArchivePath(header.Name)
247			if err != nil {
248				return nil, err
249			}
250	
251			files = append(files, ArchiveFile{
252				Path:       path,
253				Content:    content,
254				Executable: header.Mode&0o111 != 0,
255			})
256		}
257	
258		return files, nil
259	}
260	
261	// sanitizeArchivePath normalises a tar member name into a path relative to the
262	// archive root, and rejects anything that escapes it. Returning the parent
263	// references verbatim would hand a Zip Slip to any caller that writes these
264	// keys under a target directory.
265	func sanitizeArchivePath(name string) (string, error) {
266		// Tar always uses forward slashes; normalise Windows-style separators so a
267		// member named `..\..\etc\passwd` is not waved through as a plain filename.
268		clean := strings.ReplaceAll(name, `\`, "/")
269		// Drop the leading separator *before* cleaning: path.Clean("/../x") returns
270		// "/x", which would silently absorb the traversal instead of exposing it.
271		clean = path.Clean(strings.TrimLeft(clean, "/"))
272	
273		if clean == "" || clean == "." {
274			return "", fmt.Errorf("archive contains an entry with an empty path: %q", name)
275		}
276		if clean == ".." || strings.HasPrefix(clean, "../") {
277			return "", fmt.Errorf("archive entry escapes the root: %q", name)
278		}
279	
280		return clean, nil
281	}
