11	)
12	
13	// MaxRedirects is net/http's default limit, kept now that CheckRedirect is set.
14	const MaxRedirects = 10
15	
16	// RefuseOffOriginRedirect keeps credentials on the origin they were meant for.
17	// It compares with the initial request (via[0]), not only the previous hop, so
18	// a chain that leaves the origin and comes back is refused too. The redirect is
19	// refused rather than followed without Authorization: a registry that moves
20	// content to another host is misconfigured for this client, and an explicit
21	// error is safer than a silent anonymous retry.
22	func RefuseOffOriginRedirect(req *http.Request, via []*http.Request) error {
23		if len(via) >= MaxRedirects {
24			return ErrTooManyRedirects
25		}
26		if !sameOrigin(via[0].URL.String(), req.URL.String()) {
27			return fmt.Errorf("%w (%s)", ErrOffOriginRedirect, req.URL.Host)
28		}
29		return nil
30	}
31	
32	// ErrOffOriginRedirect is the refusal RefuseOffOriginRedirect returns.
33	var ErrOffOriginRedirect = errors.New("refusing redirect to another origin")
34	
35	// ErrTooManyRedirects is returned once a request was redirected MaxRedirects
36	// times. net/http wraps it in a *url.Error carrying the last target URL, so
37	// callers pass the error through StripRedirectTarget.
38	var ErrTooManyRedirects = errors.New("stopped after " + strconv.Itoa(MaxRedirects) + " redirects")
39	
40	// errInsecureRedirect is the refusal of a redirect from https to http, so a
41	// credential or a signed URL does not leave in clear.
42	var errInsecureRedirect = errors.New("refusing redirect from https to http")
43	
44	// StripRedirectTarget strips the target URL from a refused redirect. net/http
45	// wraps the refusal in a *url.Error carrying the full target URL, which may hold
46	// a signed query; only the meaning and the host (kept by the refusal itself)
47	// remain. Other errors pass through unchanged.
48	func StripRedirectTarget(err error) error {
49		var ue *url.Error
50		if !errors.As(err, &ue) {
51			return err
52		}
53		for _, sentinel := range []error{ErrOffOriginRedirect, ErrTooManyRedirects, errInsecureRedirect} {
54			if errors.Is(ue.Err, sentinel) {
55				return ue.Err
56			}
57		}
58		return err
59	}
60	
61	// ErrBodyTooLarge is returned by ReadAllLimited when the body is over the limit.
62	var ErrBodyTooLarge = errors.New("size limit exceeded")
63	
64	// ReadAllLimited reads r to its end, accepting at most limit bytes (limit >= 0;
65	// a negative limit is refused with ErrBodyTooLarge without reading). It takes
66	// limit+1 bytes at most from r: a body over the limit is an ErrBodyTooLarge, not
67	// a silent cut, and a read error is returned as is, never mistaken for a size.
68	// With limit = math.MaxInt64 the extra byte cannot be asked for, so the read is
69	// capped at limit and an overflow cannot be told apart.
70	func ReadAllLimited(r io.Reader, limit int64) ([]byte, error) {
71		if limit < 0 {
72			return nil, fmt.Errorf("response body over %d bytes: %w", limit, ErrBodyTooLarge)
73		}
74		n := limit
75		if n < math.MaxInt64 {
76			n++
77		}
78		body, err := io.ReadAll(io.LimitReader(r, n))
79		if err != nil {
80			return nil, err
81		}
82		if int64(len(body)) > limit {
83			return nil, fmt.Errorf("response body over %d bytes: %w", limit, ErrBodyTooLarge)
84		}
85		return body, nil
86	}
87	
88	// RedactURL returns raw with the password of its userinfo masked, safe to put in
89	// an error or a log. raw must be an absolute URL: one that does not parse, or
90	// that has no host (such as "user:pass@host", read as a scheme and an opaque
91	// part), is not echoed, since it may still hold a password. An empty raw stays
92	// empty.
93	func RedactURL(raw string) string {
94		if raw == "" {
95			return ""
96		}
97		u, err := url.Parse(raw)
98		if err != nil || u.Host == "" {
99			return "<invalid URL>"
100		}
101		return u.Redacted()
102	}
